تنسيق معاملات Room مع WorkManager ونظام استعادة المهام العالقة:
```kotlin
class SafeOutboxRepositoryImpl @Inject constructor(
    private val db: AppDatabase,
    private val workManager: WorkManager
) : OutboxRepository {

    override suspend fun commitAction(actionType: String, payloadJson: String) {
        val actionId = UUID.randomUUID().toString()

        // 1. الحفظ الذري في قاعدة بيانات التطبيق أولاً:
        db.withTransaction {
            db.outboxDao().insertAction(OutboxEntity(id = actionId, action = actionType, payload = payloadJson))
        }

        // 2. جدولة المهمة في WorkManager بعد نجاح المعاملة:
        dispatchSyncWork()
    }

    fun dispatchSyncWork() {
        val syncRequest = OneTimeWorkRequestBuilder<DrainOutboxWorker>()
            .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
            .build()

        // ExistingWorkPolicy.KEEP يضمن تشغيل مهمة واحدة دون تكرار:
        workManager.enqueueUniqueWork("drain_outbox_work", ExistingWorkPolicy.KEEP, syncRequest)
    }

    // 3. شبكة الأمان عند إقلاع التطبيق (Startup Reconciliation):
    suspend fun recoverPendingActionsOnStartup() {
        if (db.outboxDao().hasPendingActions()) {
            dispatchSyncWork() // إعادة جدولة العمليات العالقة لو مات التطبيق سابقاً
        }
    }
}
```

تنفيذ بروتوكول استئناف رفع الملفات الكبيرة في CoroutineWorker:
```kotlin
@HiltWorker
class ResumableUploadWorker @AssistedInject constructor(
    @Assisted context: Context,
    @Assisted params: WorkerParameters,
    private val uploadDao: UploadDao,
    private val uploadClient: ResumableHttpClient
) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        val uploadId = inputData.getString("upload_id") ?: return Result.failure()
        val record = uploadDao.getUpload(uploadId) ?: return Result.failure()

        return try {
            // 1. الحصول على رابط الجلسة (أو إنشاء جلسة جديدة لو لم تكن موجودة):
            val sessionUrl = record.sessionUrl ?: run {
                val newUrl = uploadClient.initiateSession(record.fileName, record.fileSizeBytes)
                uploadDao.updateSessionUrl(uploadId, newUrl)
                newUrl
            }

            // 2. استعلام السيرفر عن الإزاحة المؤكدة الحالية (Current Acked Offset):
            val serverOffset = uploadClient.queryCurrentOffset(sessionUrl)
            uploadDao.updateBytesAcked(uploadId, serverOffset)

            if (serverOffset >= record.fileSizeBytes) {
                uploadDao.markCompleted(uploadId)
                return Result.success()
            }

            // 3. استئناف الرفع من نقطة الانقطاع بدقة:
            val file = File(record.localFilePath)
            uploadClient.uploadRemainingChunks(
                sessionUrl = sessionUrl,
                file = file,
                startOffset = serverOffset,
                onChunkAcked = { ackedBytes ->
                    uploadDao.updateBytesAcked(uploadId, ackedBytes)
                    setProgress(workDataOf("progress" to ((ackedBytes * 100) / record.fileSizeBytes).toInt()))
                }
            )
            uploadDao.markCompleted(uploadId)
            Result.success()
        } catch (e: IOException) {
            Result.retry() // إعادة المحاولة لاحقاً واستئناف الرفع من آخر بايت مسجل!
        }
    }
}
```

تنفيذ التحقق المزدوج للـ Idempotency على العميل والسيرفر:
```kotlin
class SafeOrderWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        val orderId = inputData.getString("order_id") ?: return Result.failure()
        val db = EntryPoints.get(applicationContext, DbEntryPoint::class.java).database()
        val api = EntryPoints.get(applicationContext, ApiEntryPoint::class.java).orderApi()

        val order = db.orderDao().getOrder(orderId) ?: return Result.failure()

        // 1. الفحص المحلي: إذا كانت العملية مسجلة بالفعل كـ CONFIRMED:
        if (order.status == OrderStatus.CONFIRMED) {
            return Result.success() // تم تأكيدها مسبقاً قبل الـ Crash! نجاح فوري
        }

        // 2. إرسال الطلب مع استخدام order.id كمفتاح Idempotency ثابت:
        return try {
            val receipt = api.submitOrder(
                idempotencyKey = order.id,
                request = order.toDto()
            )
            // 3. حفظ التأكيد في Room:
            db.orderDao().updateStatus(orderId, OrderStatus.CONFIRMED, receipt.receiptId)
            Result.success()
        } catch (e: IOException) {
            Result.retry()
        }
    }
}
```

